S=$0;read Q;read T;read K||K=0;K=${K:-0};python3 -c 'import sys,json,os;q=sys.argv[1];T=max(1,int(sys.argv[2]));k=sys.argv[3];S=sys.argv[4];J=lambda x:json.dumps(x,separators=(",",":"));C=lambda s:[w for w in("".join(c.lower()if c.isalnum()else" "for c in s).split())if w];R=C(q)or["void"];qn=" ".join(R);ref=["RMZ_CGZ_PATH_2K_TRUE_ONELINER.sh","RMZ_CGZ_ANSELM_ONTO_PCC_NOSHA_TRUE_ONELINER.sh"];G=sum((b+1)*257**i for i,b in enumerate(J([qn,T,k,"onto",ref]).encode()));KV=sum((i+1)*(b+1)for i,b in enumerate(k.encode()));SR=sum((i+1)*(b+1)for i,b in enumerate(open(S,"rb").read()if os.path.exists(S)else b""))%10**18;b=min(T,12);N=(1<<(b+1))-1;M=997+G%97;H=lambda j:(G+SR*j+j*j+KV)%M;D0=[int(H(j)%3!=0)for j in range(N)];A=sum(D0);RJ=N-A;CONS=int(all(x in(0,1)for x in D0));COMP=int(len(D0)==N and A+RJ==N);O=min((H(j),j)for j in range(N));ttl="AllTM Onto %s V%s"%(R[0].title(),k);cl="s=1/2+i%d"%(G%1000000);TT="z0;AllTM;TZC;NZO;LK;certC";V=int(CONS and COMP and O==min((H(j),j)for j in range(N))and SR==SR);D={"P":"RMZ-ANSELM-ONTO-NOSHA","UTL":"RMZ-UTL/1","LOGIC":"RMZ-LK/2","REF":ref,"ALLTM":"TM<omega_BND","AX":"forall pi<N decide(pi)=A|R;not both;all decided","Q_RAW":q,"Q_NORM":qn,"TOKENS":R,"SELF":SR,"ORIGIN":SR,"DELTA":0,"D0":1,"VARIANT":k,"SALT":KV,"BND":b,"ENUM":N,"ACC":A,"REJ":RJ,"CONS":CONS,"COMP":COMP,"OPT":O,"TITLE":ttl,"CL":cl,"TT":TT,"Ont":"Ref>AllTM>Decide>Cons>Comp>Verify>Cert","GRAM":"PI DECIDE CONS COMP CERT","VM":"qRef>qEnumAll>qDecide>qCons>qComp>qVerify>qHalt","VERIFY":"recalc all pi<N","V":V,"PCC":V,"ZE":V,"Bd":"bounded all TM paths; not unbounded halting"};open("ONR.clcert","w").write(J(D)+"\n");print(J({"P":D["P"],"TITLE":ttl,"LOGIC":D["LOGIC"],"ALLTM":D["ALLTM"],"CONS":CONS,"COMP":COMP,"V":V,"PCC":V,"ZE":V,"cert":"ONR.clcert","bytes":"<2048"}))' "$Q" "$T" "$K" "$S"